window.AUTH=window.AUTH||{};window.AUTH["23-1209"]={"d":"23-1209","id":"2025/23-1209","n":"M & K Employee Solutions, LLC v. Trustees of the IAM National Pension Fund","briefs":[{"k":"petitioner","label":"Brief of petitioners M & K Employee Solutions, LLC, et al.","date":"2025-08-28","url":"https://www.supremecourt.gov/DocketPDF/23/23-1209/373166/20250828191339613_2025-08-28%20Brief%20for%20the%20Petitioners.pdf","side":"pet","n":101},{"k":"respondent","label":"Brief of respondents Trustees of the IAM National Pension Fund","date":"2025-10-14","url":"https://www.supremecourt.gov/DocketPDF/23/23-1209/379607/20251014182118752_23-1209_Brief%20of%20Respondents.pdf","side":"res","n":20},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2025-10-21","url":"https://www.supremecourt.gov/DocketPDF/23/23-1209/380210/20251021155127873_23-1209_bsac_MKEmpSols.pdf","side":"us","n":67},{"k":"reply","label":"Reply of petitioners M & K Employee Solutions, LLC, et al.","date":"2025-11-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-1209/384392/20251113135732825_Reply%20Brief%20for%20the%20Petitioners.pdf","side":"pet","n":33}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/608us1r34_f2bh.pdf","tr":true,"items":[{"t":"case","label":"Ace-Saginaw Paving Co. v. Operating Eng’rs Loc. 234 Pension Fund, — F.4th —","cite":"2025 WL 2238023","y":2025,"court":"6th Cir.","by":{"0":"29"}},{"t":"case","label":"Aetna Health Inc. v. Davila","cite":"542 U.S. 200","y":2004,"id":"2003/02-1845","sc":1,"by":{"0":"45"}},{"t":"case","label":"Atl. Mut. Ins. Co. v. Commissioner","cite":"523 U.S. 382","y":1998,"id":"1997/97-147","sc":1,"by":{"0":"24"},"q":[{"src":"brief","b":0,"text":"[a] dollar today is worth more than a dollar tomorrow,","cite":"523 U.S. 382, 384"}]},{"t":"case","label":"Barnhart v. Peabody Coal Co.","cite":"537 U.S. 149","y":2003,"id":"2002/01-705","sc":1,"by":{"0":"22"}},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"598 U.S. 69","y":2023,"id":"2022/21-908","sc":1,"by":{"0":"17"}},{"t":"case","label":"Boggs v. Boggs","cite":"520 U.S. 833","y":1997,"id":"1996/96-79","sc":1,"by":{"0":"7"},"q":[{"src":"brief","b":0,"text":"guarantee that retirement funds are there when a plan’s participants and beneficiaries expect them.","cite":"520 U.S. 833, 852"}]},{"t":"case","label":"Chi. Truck Drivers, Helpers & Warehouse Workers Union (Indep.) Pension Fund v. CPC Logistics, Inc.","cite":"698 F.3d 346","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/698/346/","by":{"0":"19, 25, 35"}},{"t":"case","label":"Citrus Valley Ests., Inc. v. Commissioner","cite":"49 F.3d 1410","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/49/1410/","by":{"0":"35"}},{"t":"case","label":"Clay v. United States","cite":"537 U.S. 522","y":2003,"id":"2002/01-1500","sc":1,"by":{"0":"32"}},{"t":"case","label":"Combs v. Classic Coal Corp.","cite":"931 F.2d 96","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/931/96/","by":{"0":"28"}},{"t":"case","label":"Concrete Pipe & Prods. of Cal., Inc. v. Constr. Laborers Pension Tr. for S. Cal.","cite":"508 U.S. 602","y":1993,"id":"1992/91-904","sc":1,"by":{"0":"5-6, 17, 25, 28, 34-36, 40","1":"8, 25, 30-31, 37-38","2":"3, 10, 12, 16, 21, 28, 29, 34","3":"21"},"q":[{"src":"brief","b":0,"text":"are pooled in a general fund available to pay any benefit obligation of the plan.","cite":"508 U.S. at 605"},{"src":"brief","b":0,"text":"described actuaries as ‘trained professionals’ who are ‘subject to regulatory standards’ and are not ‘vulnerable to suggestions of bias or its appearance.’","cite":"508 U.S. at 632"},{"src":"brief","b":1,"text":"unbiased professional[s] whose obligations tend to moderate any claimed inclination to come down hard on withdrawing employers[.]","cite":"508 U.S. at 635"},{"src":"brief","b":1,"text":"unbiased professional[s] whose [professional and regulatory] obligations tend to moderate any claimed inclination to come down hard on withdrawing employers[.]","cite":"508 U.S. at 635"},{"src":"brief","b":2,"text":"come down hard on withdrawing employers.","cite":"508 U.S. at 620, 632, 635"},{"src":"brief","b":3,"text":"one case in which a plan sponsor exercised decisive influence over an actuary whose initial assumptions it disliked.","cite":"508 U.S. 602, 633 n.19"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"maintained to fulfll the terms of collective-bargaining agreements.","cite":"508 U. S. 602, 605"},{"src":"argument","who":"Mr. Roberts","text":"Congress -- and -- and I should point out, by the way, that the fact that Congress chose actuaries to make these decisions also addresses some of this concern about gamesmanship because, in -- in the Concrete Pipe case, the Court acknowledged that Congress views actuaries as unbiased professionals who are subject to professional standards, who have absolutely no incentive to come down hard on withdrawing employers."},{"src":"argument","who":"Mr. Kenneally","text":"Concrete Pipe did describe actuaries as neutral experts, but they're not immune to client pressure, as Professor Naughton describes in his amicus brief."}]},{"t":"case","label":"Conkright v. Frommert","cite":"559 U.S. 506","y":2010,"id":"2009/08-810","sc":1,"by":{"0":"24, 44"}},{"t":"case","label":"Connolly v. PBGC","cite":"475 U.S. 211","y":1986,"id":"1985/84-1555","sc":1,"by":{"0":"9","1":"4, 5, 35","2":"3"},"q":[{"src":"brief","b":0,"text":"a withdrawing employer to fund its share of the plan obligations incurred during its association with the plan.","cite":"475 U.S. 211, 225"},{"src":"brief","b":1,"text":"to provide comprehensive regulation for private pension plans.","cite":"475 U.S. 211, 214"},{"src":"brief","b":2,"text":"Congress enacted ERISA in 1974 to provide comprehensive regulation for private pension plans.","cite":"475 U.S. 211, 214"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"comprehensive regulation for private pension plans.","cite":"475 U. S. 211, 214"}]},{"t":"case","label":"Fort Halifax Packing Co. v. Coyne","cite":"482 U.S. 1","y":1987,"id":"1986/86-341","sc":1,"by":{"0":"6"}},{"t":"case","label":"Intel Corp. Inv. Pol’y Comm. v. Sulyma","cite":"589 U.S. 178","y":2020,"id":"2019/18-1116","sc":1,"by":{"0":"17","3":"22"},"q":[{"src":"brief","b":0,"text":"enforce[s] plain and unambiguous statutory language in ERISA, as in any statute, according to its terms.","cite":"589 U.S. 178, 184"},{"src":"brief","b":3,"text":"enforce plain and unambiguous statutory language in ERISA, as in any statute, according to its terms.","cite":"589 U.S. 178, 184"}]},{"t":"case","label":"Ithaca Tr. Co. v. United States","cite":"279 U.S. 151","y":1929,"id":"scdb/1928-090","sc":1,"by":{"0":"41","2":"16, 33","3":"12-13"},"q":[{"src":"brief","b":0,"text":"to correct uncertain probabilities by the now certain fact[s].","cite":"279 U.S. 151, 155"}]},{"t":"case","label":"Joseph Schlitz Brewing Co. v. Milwaukee Brewery Workers’ Pension Plan","cite":"3 F.3d 994","y":1993,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/3/994/","by":{"0":"30","3":"18"},"q":[{"src":"brief","b":3,"text":"By instructing plans to use the amount of unfunded vested benefits at year-end, Congress has spared actuaries the need to revalue plan assets and liabilities every time an employer withdraws during the year.","cite":"3 F.3d 994, 1004"}]},{"t":"case","label":"Massachusetts v. Morash","cite":"490 U.S. 107","y":1989,"id":"1988/88-32","sc":1,"by":{"0":"5"}},{"t":"case","label":"Metro. Life Ins. Co. v. Massachusetts","cite":"471 U.S. 724","y":1985,"id":"1984/84-325","sc":1,"by":{"0":"5"},"q":[{"src":"brief","b":0,"text":"uniform procedural standards concerning reporting, disclosure, and fiduciary responsibility.","cite":"471 U.S. 724, 732"}]},{"t":"case","label":"Milwaukee Brewery Workers’ Pension Plan v. Joseph Schlitz Brewing Co.","cite":"513 U.S. 414","y":1995,"id":"1994/93-768","sc":1,"by":{"0":"1, 8-10, 14, 16-18, 20-23, 31, 43, 45","1":"1, 5, 7, 20","2":"3, 5, 6, 25, 26, 34","3":"2, 4-5, 10-11, 24"},"q":[{"src":"brief","b":0,"text":"the underfunding as calculated on December 31","cite":"513 U.S. 414, 418"},{"src":"brief","b":0,"text":"set forth a detailed set of rules for determining","cite":"513 U.S. at 417"},{"src":"brief","b":1,"text":"Unfortunately, this scheme encouraged an employer to withdraw from a financially shaky plan and risk paying its share if the plan later became insolvent, rather than to remain and (if others withdrew) risk having to bear alone the entire cost of keeping the shaky plan afloat.","cite":"513 U.S. at 416"},{"src":"brief","b":2,"text":"to withdraw from a financially shaky [multiemployer] plan * * * , rather than to remain and (if others withdrew) risk having to bear alone the entire cost of keeping the shaky plan afloat.","cite":"513 U.S. 414, 416-417"},{"src":"brief","b":2,"text":"not as of the day of withdrawal.","cite":"513 U.S. at 418"},{"src":"brief","b":3,"text":"aims to make withdrawing employers pay an actuarially perfect fair share.","cite":"513 U.S. 414, 426"},{"src":"brief","b":3,"text":"as of the last day of the plan year preceding the year during which the employer withdrew.","cite":"513 U.S. at 417"}]},{"t":"case","label":"Nachman Corp. v. PBGC","cite":"446 U.S. 359","y":1980,"id":"1979/78-1557","sc":1,"by":{"0":"5"},"q":[{"src":"brief","b":0,"text":"following almost a decade of studying the Nation’s private pension plans.","cite":"446 U.S. 359, 361"}]},{"t":"case","label":"Nat’l Ret. Fund v. Metz Culinary Mgmt., Inc.","cite":"946 F.3d 146","y":2020,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/946/146/","by":{"0":"12-13, 30, 34-35, 37","1":"2-4, 11-16, 20, 28, 34-36","2":"7, 10, 18, 19, 22, 24, 28","3":"15, 21, 23"}},{"t":"case","label":"PBGC v. R.A. Gray & Co.","cite":"467 U.S. 717","y":1984,"id":"1983/83-245","sc":1,"by":{"0":"8-9, 17, 23","1":"4-6","2":"4"},"q":[{"src":"brief","b":0,"text":"is the employer’s proportionate share of the plan’s ‘unfunded vested benefits,’ calculated as the difference between the present value of vested benefits and the current value of the plan’s assets.","cite":"467 U.S. at 725"},{"src":"brief","b":0,"text":"the difference between the present value of vested benefits and the current value of the plan’s assets.","cite":"467 U.S. at 725"},{"src":"brief","b":1,"text":"if a worker has been promised a defined pension benefit upon retirement—and if he has fulfilled whatever conditions are required to obtain a vested benefit—he actually will receive it.","cite":"467 U.S. 717, 720"},{"src":"brief","b":2,"text":"to pay whatever share of the plan’s unfunded vested liabilities was attributable to that employer’s participation.","cite":"467 U.S. 717, 723"}]},{"t":"case","label":"Rhoades, McKee & Boer v. United States","cite":"43 F.3d 1071","y":1995,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/43/1071/","by":{"0":"35"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"by":{"0":"44-45"},"q":[{"src":"brief","b":0,"text":"frustrates rather than effectuates legislative intent simplistically to assume that whatever furthers the statute’s primary objective must be the law.","cite":"480 U.S. at 525"}]},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"0":"31-32","1":"18","2":"19","3":"18"}},{"t":"case","label":"Sofco Erectors, Inc. v. Trs. of Ohio Operating Eng’rs Pension Fund","cite":"15 F.4th 407","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/15/407/","by":{"0":"25, 28, 36, 39","2":"4, 31","3":"6, 24"},"q":[{"src":"brief","b":0,"text":"assumptions about the income the [plan’s] assets will generate.","cite":"15 F.4th 407, 418-419"},{"src":"brief","b":3,"text":"ERISA does not yield to the Actuarial Standards of Practice.","cite":"15 F.4th at 423"},{"src":"argument","who":"Mr. Roberts","text":"There are -- there are cases, the Sofco case, the Energy West case, in which courts have struck down or -- or asked actuaries to recalculate withdrawal liability because they found that the assumptions were either unreasonable or didn't satisfy the best estimate requirement."},{"src":"argument","who":"Mr. Kenneally","text":"That rule would abrogate the Sofco case that Mr. Roberts cited as his example for how those rule -- those standards have teeth. The PBGC rule would replace that part of the statutory inquiry, and the only thing that could protect a employer from getting a surprise bill months or even years after the withdrawal would be the timing rule that we argue is already inherent in the \"as of\" language in Section 1391."}]},{"t":"case","label":"Till v. SCS Credit Corp.","cite":"541 U.S. 465","y":2004,"id":"2003/02-1016","sc":1,"by":{"0":"24"}},{"t":"case","label":"Trs. of IAM Nat’l Pension Fund v. M & K Emp. Sols., LLC","cite":"92 F.4th 316","y":2024,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/92/316/","by":{"0":"4"}},{"t":"case","label":"Trs. of IAM Nat’l Pension Fund v. M & K Emp. Sols., LLC","cite":"2022 WL 4534998","y":2022,"court":"D.D.C. Sept. 28","by":{"0":"4"}},{"t":"case","label":"Trs. of IAM Nat’l Pension Fund v. Ohio Magnetics, Inc.","cite":"656 F. Supp. 3d 112","y":2023,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/656/112/","by":{"0":"4"}},{"t":"case","label":"United Mine Workers of Am. 1974 Pension Plan v. Energy W. Mining Co.","cite":"39 F.4th 730","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/39/730/","by":{"0":"28, 34, 39","1":"8","2":"30, 31","3":"11"},"q":[{"src":"brief","b":3,"text":"if the Best Estimate Requirement meant an actuary had to pick the single point assumption that he thought was ‘the most likely result,’ then the requirement that the assumptions be ‘reasonable’ would be ‘superfluous.’","cite":"39 F.4th 730, 739"}]},{"t":"case","label":"Vinson & Elkins v. Commissioner","cite":"7 F.3d 1235","y":1993,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/7/1235/","by":{"0":"35"}},{"t":"case","label":"Wachtell, Lipton, Rosen & Katz v. Commissioner","cite":"26 F.3d 291","y":1994,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/26/291/","by":{"0":"34","1":"16, 31"},"q":[{"src":"brief","b":0,"text":"designed to ensure that the chosen assumptions actually represent the actuary’s own judgment rather than the dictates of plan administrators or sponsors.","cite":"26 F.3d 291, 296"}]},{"t":"usc","label":"26 U.S.C. § 412","url":"https://www.law.cornell.edu/uscode/text/26/412","subs":["(a)(1)","(c)(9)(1976)","(c)(9)(1982)","(c)(3)","(c)(9)"],"by":{"0":"43, 7, 8, 43","3":"10, 10"}},{"t":"usc","label":"26 U.S.C. § 431","url":"https://www.law.cornell.edu/uscode/text/26/431","subs":["(c)(7)(A)"],"by":{"0":"8"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"5"}},{"t":"law","label":"Pub. L. No. 99-272","url":"https://www.govinfo.gov/link/statute/100/82","by":{"0":"7"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","by":{"0":"5","2":"1, 18, 19, 21, 25-28, 33, 34"}},{"t":"usc","label":"29 U.S.C. § 1001a","url":"https://www.law.cornell.edu/uscode/text/29/1001a","subs":["(c)","(c)(2)"],"by":{"0":"13, 44, 44"},"q":[{"src":"brief","b":0,"text":"Metz’s reasoning is counter to the text of the MPPAA, which protects [multiemployer pension plans] and their beneficiaries.","cite":"29 U.S.C. 1001a(c)"},{"src":"brief","b":0,"text":"the maintenance and growth of multiemployer pension plans.","cite":"29 U.S.C. 1001a(c)(2)"}]},{"t":"usc","label":"29 U.S.C. § 1002","url":"https://www.law.cornell.edu/uscode/text/29/1002","subs":["(2)","(37)","(37)(A)"],"by":{"0":"5, 5, 5, 32"}},{"t":"usc","label":"29 U.S.C. § 1021","url":"https://www.law.cornell.edu/uscode/text/29/1021","subs":["(l)","(l)(1)(A)"],"stext":{"head":"§1021. Duty of disclosure and reporting","paras":[[0,"(a) Summary plan description and information to be furnished to participants and beneficiaries"],[0,"The administrator of each employee benefit plan shall cause to be furnished in accordance with section 1024(b) of this title to each participant covered under the plan and to each beneficiary who is receiving benefits under the plan—"],[1,"(1) a summary plan description described in section 1022(a)(1) 1 of this title; and"],[1,"(2) the information described in subsection (f) and sections 1024(b)(3) and 1025(a) and (c) of this title."],[0,"(b) Reports to be filed with Secretary of Labor"],[0,"The administrator shall, in accordance with section 1024(a) of this title, file with the Secretary—"],[1,"(1) the annual report containing the information required by section 1023 of this title; and"],[1,"(2) terminal and supplementary reports as required by subsection (c) of this section."],[0,"(c) Terminal and supplementary reports"],[0,"(1) Each administrator of an employee pension benefit plan which is winding up its affairs (without regard to the number of participants remaining in the plan) shall, in accordance with regulations prescribed by the Secretary, file such terminal reports as the Secretary may consider necessary. A copy of such report shall also be filed with the Pension Benefit Guaranty Corporation."],[0,"(2) The Secretary may require terminal reports to be filed with regard to any employee welfare benefit plan which is winding up its affairs in accordance with regulations promulgated by the Secretary."],[0,"(3) The Secretary may require that a plan described in paragraph (1) or (2) file a supplementary or terminal report with the annual report in the year such plan is terminated and that a copy of such supplementary or terminal report in the case of a plan described in paragraph (1) be also filed with the Pension Benefit Guaranty Corporation."],[0,"(d) Notice of failure to meet minimum funding standards"],[0,"(1) In general"],[1,"If an employer maintaining a plan other than a multiemployer plan fails to make a required installment or other payment required to meet the minimum funding standard under section 1082 of this title to a plan before the 60th day following the due date for such installment or other payment, the employer shall notify each participant and beneficiary (including an alternate payee as defined in section 1056(d)(3)(K) of this title) of such plan of such failure. Such notice shall be made at such time and in such manner as the Secretary may prescribe."],[0,"(2) Subsection not to apply if waiver pending"],[1,"This subsection shall not apply to any failure if the employer has filed a waiver request under section 1083 or 1085a of this title with respect to the plan year to which the required installment relates, except that if the waiver request is denied, notice under paragraph (1) shall be provided within 60 days after the date of such denial."],[0,"(3) Definitions"],[1,"For purposes of this subsection, the terms \"required installment\" and \"due date\" have the same meanings given such terms by section 1083(j) or 1085a(f) of this title, whichever is applicable."],[0,"(e) Notice of transfer of excess pension assets to health benefits accounts"],[0,"(1) Notice to participants"],[1,"Not later than 60 days before the date of a qualified transfer by an employee pension benefit plan of excess pension assets to a health benefits account or applicable life insurance account, the administrator of the plan shall notify (in such manner as the Secretary may prescribe) each participant and beneficiary under the plan of such transfer. Such notice shall include information with respect to the amount of excess pension assets, the portion to be transferred, the amount of health benefits liabilities or applicable life insurance benefit liabilities expected to be provided with the assets transferred, and the amount of pension benefits of the participant which will be nonforfeitable immediately after the transfer."],[0,"(2) Notice to Secretaries, administrator, and employee organizations"],[0,"(A) In general"],[2,"Not later than 60 days before the date of any qualified transfer by an employee pension benefit plan of excess pension assets to a health benefits account or applicable life insurance account, the employer maintaining the plan from which the transfer is made shall provide the Secretary, the Secretary of the Treasury, the administrator, and each employee organization representing participants in the plan a written notice of such transfer. A copy of any such notice shall be available for inspection in the principal office of the administrator."],[0,"(B) Information relating to transfer"],[2,"Such notice shall identify the plan from which the transfer is made, the amount of the transfer, a detailed accounting of assets projected to be held by the plan immediately before and immediately after the transfer, and the current liabilities under the plan at the time of the transfer."],[0,"(C) Authority for additional reporting requirements"],[2,"The Secretary may prescribe such additional reporting requirements as may be necessary to carry out the purposes of this section."],[0,"(3) Definitions"],[1,"For purposes of paragraph (1), any term used in such paragraph which is also used in section 420 of title 26 (as in effect on December 29, 2022) shall have the same meaning as when used in such section."],[0,"(f) Defined benefit plan funding notices"],[0,"(1) In general"],[1,"The administrator of a defined benefit plan to which subchapter III applies shall for each plan year provide a plan funding notice to the Pension Benefit Guaranty Corporation, to each plan participant and beneficiary, to each labor organization representing such participants or beneficiaries, and, in the case of a multiemployer plan, to each employer that has an obligation to contribute to the plan."],[0,"(2) Information contained in notices"],[0,"(A) Identifying information"],[2,"Each notice required under paragraph (1) shall contain identifying information, including the name of the plan, the address and phone number of the plan administrator and the plan's principal administrative officer, each plan sponsor's employer identification number, and the plan number of the plan."],[0,"(B) Specific information"],[2,"A plan funding notice under paragraph (1) shall include—"],[3,"(i)(I) in the case of a single-employer plan, a statement as to whether the plan's percentage of plan liabilities funded (as described in clause (ii)(I)(bb)) for the plan year to which the notice relates, and for the 2 preceding plan years, is at least 100 percent (and, if not, the actual percentages), or"],[3,"(II) in the case of a multiemployer plan, a statement as to whether the plan's funded percentage (as defined in section 1085(i) 1 of this title) for the plan year to which the notice relates, and for the 2 preceding plan years, is at least 100 percent (and, if not, the actual percentages),"],[3,"(ii)(I) in the case of a single-employer plan—"],[4,"(aa) a statement of the value of the plan's assets and liabilities for the plan year to which the notice relates as of the last day of the plan year to which the notice relates, and for the preceding 2 plan years as of the last day of each such plan year, determined using the asset valuation under subclause (II) of section 1306(a)(3)(E)(iii) of this title and the interest rate under section 1306(a)(3)(E)(iv) of this title,"],[4,"(bb) for purposes of the statement in subparagraph (B)(i)(I), the percentage of plan liabilities funded, calculated as the ratio between the value of the plan's assets and liabilities, as determined under item (aa), for the plan year to which the notice relates and for the 2 preceding plan years, and"],[4,"(cc) if the information in (aa) and (bb) is presented in tabular form, a statement that describes that in the event of a plan termination the corporation's calculation of plan liabilities may be greater and that references the section of the notice with the information required under clause (x), and"],[3,"(II) in the case of a multiemployer plan, a statement, for the plan year to which the notice relates and the preceding 2 plan years, of the value of the plan assets (determined both in the same manner as under section 1084 of this title and under the rules of subclause (I)(aa)) and the value of the plan liabilities (determined in the same manner as under section 1084 of this title except that the method specified in section 1085(i)(8) 1 of this title shall be used),"],[3,"(iii) a statement of the number of participants for the plan year to which the notice relates as of the last day of such plan year and the preceding 2 plan years, in tabular format, who are—"],[4,"(I) retired or separated from service and are receiving benefits,"],[4,"(II) retired or separated participants entitled to future benefits, and"],[4,"(III) active participants under the plan,"],[3,"(iv) a statement setting forth the funding policy of the plan, the asset allocation of investments under the plan (expressed as percentages of total assets), and the average return on assets for the plan year, as of the end of the plan year to which the notice relates,"],[3,"(v) in the case of a multiemployer plan, whether the plan was in critical or endangered status under section 1085 of this title for such plan year and, if so—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1021?type=usc&year=mostrecent&link-type=html"},"by":{"0":"34, 34","2":"24, 24"},"q":[{"src":"brief","b":2,"text":"[as] if such employer withdrew on the last day of the plan year preceding the date of the request","cite":"29 U.S.C. 1021(l)(1)(A)"}]},{"t":"usc","label":"29 U.S.C. § 1023","url":"https://www.law.cornell.edu/uscode/text/29/1023","subs":["(a)(1)(A)","(a)(1)(B)(ii)","(a)(4)(A)","(a)(4)(B)(ii)(1982)","(d)","(d)(1976)","(d)(6)","(d)(6)(1976)","(a)(4)(B)","(a)(4)(B)(ii)"],"stext":{"head":"§1023. Annual reports","paras":[[0,"(a) Publication and filing"],[0,"(1)(A) An annual report shall be published with respect to every employee benefit plan to which this part applies. Such report shall be filed with the Secretary in accordance with section 1024(a) of this title, and shall be made available and furnished to participants in accordance with section 1024(b) of this title."],[0,"(B) The annual report shall include the information described in subsections (b) and (c) and where applicable subsections (d), (e), (f), and (g) and shall also include—"],[1,"(i) a financial statement and opinion, as required by paragraph (3) of this subsection, and"],[1,"(ii) an actuarial statement and opinion, as required by paragraph (4) of this subsection."],[0,"(2) If some or all of the information necessary to enable the administrator to comply with the requirements of this subchapter is maintained by—"],[1,"(A) an insurance carrier or other organization which provides some or all of the benefits under the plan, or holds assets of the plan in a separate account,"],[1,"(B) a bank or similar institution which holds some or all of the assets of the plan in a common or collective trust or a separate trust, or custodial account, or"],[1,"(C) a plan sponsor as defined in section 1002(16)(B) of this title,"],[0,"such carrier, organization, bank, institution, or plan sponsor shall transmit and certify the accuracy of such information to the administrator within 120 days after the end of the plan year (or such other date as may be prescribed under regulations of the Secretary)."],[0,"(3)(A) Except as provided in subparagraph (C), the administrator of an employee benefit plan shall engage, on behalf of all plan participants, an independent qualified public accountant, who shall conduct such an examination of any financial statements of the plan, and of other books and records of the plan, as the accountant may deem necessary to enable the accountant to form an opinion as to whether the financial statements and schedules required to be included in the annual reports by subsection (b) of this section are presented fairly in conformity with generally accepted accounting principles applied on a basis consistent with that of the preceding year. Such examination shall be conducted in accordance with generally accepted auditing standards, and shall involve such tests of the books and records of the plan as are considered necessary by the independent qualified public accountant. The independent qualified public accountant shall also offer his opinion as to whether the separate schedules specified in subsection (b)(3) of this section and the summary material required under section 1024(b)(3) of this title present fairly, and in all material respects the information contained therein when considered in conjunction with the financial statements taken as a whole. The opinion by the independent qualified public accountant shall be made a part of the annual report. In a case where a plan is not required to file an annual report, the requirements of this paragraph shall not apply. In a case where by reason of section 1024(a)(2) of this title a plan is required only to file a simplified annual report, the Secretary may waive the requirements of this paragraph."],[0,"(B) In offering his opinion under this section the accountant may rely on the correctness of any actuarial matter certified to by an enrolled actuary, if he so states his reliance."],[0,"(C) The opinion required by subparagraph (A) need not be expressed as to any statements required by subsection (b)(3)(G) prepared by a bank or similar institution or insurance carrier regulated and supervised and subject to periodic examination by a State or Federal agency if such statements are certified by the bank, similar institution, or insurance carrier as accurate and are made a part of the annual report."],[0,"(D) For purposes of this subchapter, the term \"qualified public accountant\" means—"],[1,"(i) a person who is a certified public accountant, certified by a regulatory authority of a State;"],[1,"(ii) a person who is a licensed public accountant licensed by a regulatory authority of a State; or"],[1,"(iii) a person certified by the Secretary as a qualified public accountant in accordance with regulations published by him for a person who practices in States where there is no certification or licensing procedure for accountants."],[0,"(4)(A) The administrator of an employee pension benefit plan subject to the reporting requirement of subsection (d) of this section shall engage, on behalf of all plan participants, an enrolled actuary who shall be responsible for the preparation of the materials comprising the actuarial statement required under subsection (d) of this section. In a case where a plan is not required to file an annual report, the requirement of this paragraph shall not apply, and, in a case where by reason of section 1024(a)(2) of this title, a plan is required only to file a simplified report, the Secretary may waive the requirement of this paragraph."],[0,"(B) The enrolled actuary shall utilize such assumptions and techniques as are necessary to enable him to form an opinion as to whether the contents of the matters reported under subsection (d) of this section—"],[1,"(i) are in the aggregate reasonably related to the experience of the plan and to reasonable expectations; and"],[1,"(ii) represent his best estimate of anticipated experience under the plan."],[0,"The opinion by the enrolled actuary shall be made with respect to, and shall be made a part of, each annual report."],[0,"(C) For purposes of this subchapter, the term \"enrolled actuary\" means an actuary enrolled under subtitle C of subchapter II of this chapter."],[0,"(D) In making a certification under this section the enrolled actuary may rely on the correctness of any accounting matter under subsection (b) to which any qualified public accountant has expressed an opinion, if he so states his reliance."],[0,"(b) Financial statement"],[0,"An annual report under this section shall include a financial statement containing the following information:"],[0,"(1) With respect to an employee welfare benefit plan: a statement of assets and liabilities; a statement of changes in fund balance; and a statement of changes in financial position. In the notes to financial statements, disclosures concerning the following items shall be considered by the accountant: a description of the plan including any significant changes in the plan made during the period and the impact of such changes on benefits; a description of material lease commitments, other commitments, and contingent liabilities; a description of agreements and transactions with persons known to be parties in interest; a general description of priorities upon termination of the plan; information concerning whether or not a tax ruling or determination letter has been obtained; and any other matters necessary to fully and fairly present the financial statements of the plan."],[0,"(2) With respect to an employee pension benefit plan: a statement of assets and liabilities, and a statement of changes in net assets available for plan benefits which shall include details of revenues and expenses and other changes aggregated by general source and application. In the notes to financial statements, disclosures concerning the following items shall be considered by the accountant: a description of the plan including any significant changes in the plan made during the period and the impact of such changes on benefits; the funding policy (including policy with respect to prior service cost), and any changes in such policies during the year; a description of any significant changes in plan benefits made during the period; a description of material lease commitments, other commitments, and contingent liabilities; a description of agreements and transactions with persons known to be parties in interest; a general description of priorities upon termination of the plan; information concerning whether or not a tax ruling or determination letter has been obtained; and any other matters necessary to fully and fairly present the financial statements of such pension plan."],[0,"(3) With respect to all employee benefit plans, the statement required under paragraph (1) or (2) shall have attached the following information in separate schedules:"],[1,"(A) a statement of the assets and liabilities of the plan aggregated by categories and valued at their current value, and the same data displayed in comparative form for the end of the previous fiscal year of the plan;"],[1,"(B) a statement of receipts and disbursements during the preceding twelve-month period aggregated by general sources and applications;"],[1,"(C) a schedule of all assets held for investment purposes aggregated and identified by issuer, borrower, or lessor, or similar party to the transaction (including a notation as to whether such party is known to be a party in interest), maturity date, rate of interest, collateral, par or maturity value, cost, and current value;"],[1,"(D) a schedule of each transaction involving a person known to be party in interest, the identity of such party in interest and his relationship or that of any other party in interest to the plan, a description of each asset to which the transaction relates; the purchase or selling price in case of a sale or purchase, the rental in case of a lease, or the interest rate and maturity date in case of a loan; expense incurred in connection with the transaction; the cost of the asset, the current value of the asset, and the net gain (or loss) on each transaction;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1023?type=usc&year=mostrecent&link-type=html"},"by":{"0":"33, 6, 6, 6, 26, 6, 7, 7, 6","2":"25, 27","3":"9, 9, 9, 9"},"q":[{"src":"brief","b":0,"text":"an actuar- ial statement and opinion.","cite":"29 U.S.C. 1023(a)(1)(B)(ii)"},{"src":"brief","b":0,"text":"en- gage * * * an enrolled actuary who shall be responsi- ble for the preparation of the materials comprising the actuarial statement.","cite":"29 U.S.C. 1023(a)(4)(A)"},{"src":"brief","b":3,"text":"best estimate of anticipated experience under the plan.","cite":"29 U.S.C. 1023(a)(4)(B)(ii)"},{"src":"brief","b":3,"text":"actuary shall make an actuarial valuation of the plan for every third plan year, unless he determines that a more frequent valuation is necessary to support his opinion under subsection (a)(4) of this section.","cite":"29 U.S.C. 1023(d)"}]},{"t":"usc","label":"29 U.S.C. § 1024","url":"https://www.law.cornell.edu/uscode/text/29/1024","subs":["(a)(1)"],"by":{"0":"6, 33","2":"25"}},{"t":"usc","label":"29 U.S.C. § 1082","url":"https://www.law.cornell.edu/uscode/text/29/1082","subs":["(a)(1)","(c)(3)(1982)","(c)(9)(1976)","(c)(9)(1994)"],"by":{"0":"7, 26, 8","2":"6, 25, 26"}},{"t":"usc","label":"29 U.S.C. § 1084","url":"https://www.law.cornell.edu/uscode/text/29/1084","subs":["(c)(7)(A)","(c)(3)","(c)(7)","(c)(7)(B)(i)"],"by":{"0":"8","2":"29, 5, 27, 30, 6, 23, 25, 26, 26, 26"},"q":[{"src":"brief","b":2,"text":"a determination of experience gains and losses and a valuation of the plan’s liability * * * not less frequently than once every year.","cite":"29 U.S.C. 1084(c)(7)(A)"}]},{"t":"usc","label":"29 U.S.C. § 1341a","url":"https://www.law.cornell.edu/uscode/text/29/1341a","subs":["(c)(2)"],"by":{"0":"28"}},{"t":"usc","label":"29 U.S.C. § 1365","url":"https://www.law.cornell.edu/uscode/text/29/1365","subs":["(3)(A)(i)"],"by":{"0":"6-7, 33"}},{"t":"usc","label":"29 U.S.C. § 1381","url":"https://www.law.cornell.edu/uscode/text/29/1381","subs":["(b)(1)","(a)"],"by":{"0":"9, 9, 18","2":"2, 4, 4, 5"}},{"t":"usc","label":"29 U.S.C. § 1389","url":"https://www.law.cornell.edu/uscode/text/29/1389","by":{"0":"45","2":"19"},"q":[{"src":"argument","who":"Mr. Kenneally","text":"And given Congress's demonstrated concern about retroactive changes in such things as the de minimis reduction or switching between allocation methods -- and the de minimis reduction in Section 1389 is a question of about a hundred thousand dollars to a given employer -- the idea that they would have been completely unconcerned about millions of dollars of a delta by changing actuarial assumptions is really hard to swallow."}]},{"t":"usc","label":"29 U.S.C. § 1390","url":"https://www.law.cornell.edu/uscode/text/29/1390","by":{"0":"31"}},{"t":"usc","label":"29 U.S.C. § 1391","url":"https://www.law.cornell.edu/uscode/text/29/1391","subs":["(a)","(b)(2)(A)(ii)","(b)(2)(C)","(b)(2)(E)","(b)(2)(E)(i)","(c)(2)(C)(i)","(c)(2)(C)(i)(I)","(c)(3)(A)","(c)(3)(B)","(c)(4)(A)","(c)(4)(A)(i)","(c)","(b)(2)(A)","(b)(2)(E)(ii)"],"stext":{"head":"§1391. Methods for computing withdrawal liability","paras":[[0,"(a) Determination of amount of unfunded vested benefits allocable to employer withdrawn from plan"],[0,"The amount of the unfunded vested benefits allocable to an employer that withdraws from a plan shall be determined in accordance with subsection (b), (c), or (d) of this section."],[0,"(b) Factors determining computation of amount of unfunded vested benefits allocable to employer withdrawn from plan"],[0,"(1) Except as provided in subsections (c) and (d), the amount of unfunded vested benefits allocable to an employer that withdraws is the sum of—"],[1,"(A) the employer's proportional share of the unamortized amount of the change in the plan's unfunded vested benefits for plan years ending after September 25, 1980, as determined under paragraph (2),"],[1,"(B) the employer's proportional share, if any, of the unamortized amount of the plan's unfunded vested benefits at the end of the plan year ending before September 26, 1980, as determined under paragraph (3); and"],[1,"(C) the employer's proportional share of the unamortized amounts of the reallocated unfunded vested benefits (if any) as determined under paragraph (4)."],[0,"If the sum of the amounts determined with respect to an employer under paragraphs (2), (3), and (4) is negative, the unfunded vested benefits allocable to the employer shall be zero."],[0,"(2)(A) An employer's proportional share of the unamortized amount of the change in the plan's unfunded vested benefits for plan years ending after September 25, 1980, is the sum of the employer's proportional shares of the unamortized amount of the change in unfunded vested benefits for each plan year in which the employer has an obligation to contribute under the plan ending—"],[1,"(i) after such date, and"],[1,"(ii) before the plan year in which the withdrawal of the employer occurs."],[0,"(B) The change in a plan's unfunded vested benefits for a plan year is the amount by which—"],[1,"(i) the unfunded vested benefits at the end of the plan year; exceeds"],[1,"(ii) the sum of—"],[2,"(I) the unamortized amount of the unfunded vested benefits for the last plan year ending before September 26, 1980, and"],[2,"(II) the sum of the unamortized amounts of the change in unfunded vested benefits for each plan year ending after September 25, 1980, and preceding the plan year for which the change is determined."],[0,"(C) The unamortized amount of the change in a plan's unfunded vested benefits with respect to a plan year is the change in unfunded vested benefits for the plan year, reduced by 5 percent of such change for each succeeding plan year."],[0,"(D) The unamortized amount of the unfunded vested benefits for the last plan year ending before September 26, 1980, is the amount of the unfunded vested benefits as of the end of that plan year reduced by 5 percent of such amount for each succeeding plan year."],[0,"(E) An employer's proportional share of the unamortized amount of a change in unfunded vested benefits is the product of—"],[1,"(i) the unamortized amount of such change (as of the end of the plan year preceding the plan year in which the employer withdraws); multiplied by"],[1,"(ii) a fraction—"],[2,"(I) the numerator of which is the sum of the contributions required to be made under the plan by the employer for the year in which such change arose and for the 4 preceding plan years, and"],[2,"(II) the denominator of which is the sum for the plan year in which such change arose and the 4 preceding plan years of all contributions made by employers who had an obligation to contribute under the plan for the plan year in which such change arose reduced by the contributions made in such years by employers who had withdrawn from the plan in the year in which the change arose."],[0,"(3) An employer's proportional share of the unamortized amount of the plan's unfunded vested benefits for the last plan year ending before September 26, 1980, is the product of—"],[1,"(A) such unamortized amount; multiplied by—"],[1,"(B) a fraction—"],[2,"(i) the numerator of which is the sum of all contributions required to be made by the employer under the plan for the most recent 5 plan years ending before September 26, 1980, and"],[2,"(ii) the denominator of which is the sum of all contributions made for the most recent 5 plan years ending before September 26, 1980, by all employers—"],[3,"(I) who had an obligation to contribute under the plan for the first plan year ending on or after such date, and"],[3,"(II) who had not withdrawn from the plan before such date."],[0,"(4)(A) An employer's proportional share of the unamortized amount of the reallocated unfunded vested benefits is the sum of the employer's proportional share of the unamortized amount of the reallocated unfunded vested benefits for each plan year ending before the plan year in which the employer withdrew from the plan."],[0,"(B) Except as otherwise provided in regulations prescribed by the corporation, the reallocated unfunded vested benefits for a plan year is the sum of—"],[1,"(i) any amount which the plan sponsor determines in that plan year to be uncollectible for reasons arising out of cases or proceedings under title 11, or similar proceedings.1"],[1,"(ii) any amount which the plan sponsor determines in that plan year will not be assessed as a result of the operation of section 1389, 1399(c)(1)(B), or 1405 of this title against an employer to whom a notice described in section 1399 of this title has been sent, and"],[1,"(iii) any amount which the plan sponsor determines to be uncollectible or unassessable in that plan year for other reasons under standards not inconsistent with regulations prescribed by the corporation."],[0,"(C) The unamortized amount of the reallocated unfunded vested benefits with respect to a plan year is the reallocated unfunded vested benefits for the plan year, reduced by 5 percent of such reallocated unfunded vested benefits for each succeeding plan year."],[0,"(D) An employer's proportional share of the unamortized amount of the reallocated unfunded vested benefits with respect to a plan year is the product of—"],[1,"(i) the unamortized amount of the reallocated unfunded vested benefits (as of the end of the plan year preceding the plan year in which the employer withdraws); multiplied by"],[1,"(ii) the fraction defined in paragraph (2)(E)(ii)."],[0,"(c) Amendment of multiemployer plan for determination respecting amount of unfunded vested benefits allocable to employer withdrawn from plan; factors determining computation of amount"],[0,"(1) A multiemployer plan, other than a plan which primarily covers employees in the building and construction industry, may be amended to provide that the amount of unfunded vested benefits allocable to an employer that withdraws from the plan is an amount determined under paragraph (2), (3), (4), or (5) of this subsection, rather than under subsection (b) or (d). A plan described in section 1383(b)(1)(B)(i) of this title (relating to the building and construction industry) may be amended, to the extent provided in regulations prescribed by the corporation, to provide that the amount of the unfunded vested benefits allocable to an employer not described in section 1383(b)(1)(A) of this title shall be determined in a manner different from that provided in subsection (b)."],[0,"(2)(A) The amount of the unfunded vested benefits allocable to any employer under this paragraph is the sum of the amounts determined under subparagraphs (B) and (C)."],[0,"(B) The amount determined under this subparagraph is the product of—"],[1,"(i) the plan's unfunded vested benefits as of the end of the last plan year ending before September 26, 1980, reduced as if those obligations were being fully amortized in level annual installments over 15 years beginning with the first plan year ending on or after such date; multiplied by"],[1,"(ii) a fraction—"],[2,"(I) the numerator of which is the sum of all contributions required to be made by the employer under the plan for the last 5 plan years ending before September 26, 1980, and"],[2,"(II) the denominator of which is the sum of all contributions made for the last 5 plan years ending before September 26, 1980, by all employers who had an obligation to contribute under the plan for the first plan year ending after September 25, 1980, and who had not withdrawn from the plan before such date."],[0,"(C) The amount determined under this subparagraph is the product of—"],[1,"(i) an amount equal to—"],[2,"(I) the plan's unfunded vested benefits as of the end of the plan year preceding the plan year in which the employer withdraws, less"],[2,"(II) the sum of the value as of such date of all outstanding claims for withdrawal liability which can reasonably be expected to be collected, with respect to employers withdrawing before such plan year, and that portion of the amount determined under subparagraph (B)(i) which is allocable to employers who have an obligation to contribute under the plan in the plan year preceding the plan year in which the employer withdraws and who also had an obligation to contribute under the plan for the first plan year ending after September 25, 1980; multiplied by"],[1,"(ii) a fraction—"],[2,"(I) the numerator of which is the total amount required to be contributed under the plan by the employer for the last 5 plan years ending before the date on which the employer withdraws, and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1391?type=usc&year=mostrecent&link-type=html"},"by":{"0":"18, 18, 19, 19, 20, 1, 9, 14, 18, 1, 9, 14, 18, 20, 1, 9, 14, 18-19, 19, 1, 9, 14, 18, 20","2":"2, 5, 9-11, 13-15, 18-21, 23, 24, 26-28, 31, 32, 5, 11, 14, 19","3":"1, 3, 5-8, 11, 16-20, 22, 24, 4, 3-4, 4, 3, 3, 3"},"q":[{"src":"brief","b":0,"text":"as of the end of the plan year preceding the plan year in which the employer withdraws.","cite":"29 U.S.C. 1391(b)(2)(E)(i)"},{"src":"brief","b":2,"text":"as of the end of the plan year preceding the plan year in which the employer withdraws,","cite":"29 U.S.C. 1391(b)(2)(E)(i)"},{"src":"brief","b":3,"text":"as of the end of the plan year preceding the plan year in which the employer withdraws.","cite":"29 U.S.C. 1391(b)(2)(E)(i)"},{"src":"argument","who":"Mr. Kenneally","text":"Chief Justice, and may it please the Court: Section 1391 creates a clear timing rule. Withdrawal liability is based on the plan's unfunded vested benefits as of the end of the prior year."},{"src":"argument","who":"Mr. Barber","text":"Section 1391's \"as of\" language plainly contemplates a retrospective determination of withdrawal liability, and nothing in that section suggests a different rule for the underlying actuarial assumptions."},{"src":"argument","who":"Mr. Kenneally","text":"The PBGC rule would replace that part of the statutory inquiry, and the only thing that could protect a employer from getting a surprise bill months or even years after the withdrawal would be the timing rule that we argue is already inherent in the \"as of\" language in Section 1391."}]},{"t":"usc","label":"29 U.S.C. § 1393","url":"https://www.law.cornell.edu/uscode/text/29/1393","subs":["(a)","(a)(1)","(a)(1)(1982)","(b)","(b)(1)","(c)","(c)(A)","(a)(2)","(b)(2)"],"stext":{"head":"§1393. Actuarial assumptions","paras":[[0,"(a) Use by plan actuary in determining unfunded vested benefits of a plan for computing withdrawal liability of employer"],[0,"The corporation may prescribe by regulation actuarial assumptions which may be used by a plan actuary in determining the unfunded vested benefits of a plan for purposes of determining an employer's withdrawal liability under this part. Withdrawal liability under this part shall be determined by each plan on the basis of—"],[1,"(1) actuarial assumptions and methods which, in the aggregate, are reasonable (taking into account the experience of the plan and reasonable expectations) and which, in combination, offer the actuary's best estimate of anticipated experience under the plan, or"],[1,"(2) actuarial assumptions and methods set forth in the corporation's regulations for purposes of determining an employer's withdrawal liability."],[0,"(b) Factors determinative of unfunded vested benefits of plan for computing withdrawal liability of employer"],[0,"In determining the unfunded vested benefits of a plan for purposes of determining an employer's withdrawal liability under this part, the plan actuary may—"],[1,"(1) rely on the most recent complete actuarial valuation used for purposes of section 412 of title 26 and reasonable estimates for the interim years of the unfunded vested benefits, and"],[1,"(2) in the absence of complete data, rely on the data available or on data secured by a sampling which can reasonably be expected to be representative of the status of the entire plan."],[0,"(c) Determination of amount of unfunded vested benefits"],[0,"For purposes of this part, the term \"unfunded vested benefits\" means with respect to a plan, an amount equal to—"],[1,"(A) the value of nonforfeitable benefits under the plan, less"],[1,"(B) the value of the assets of the plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1393?type=usc&year=mostrecent&link-type=html"},"by":{"0":"16, 29, 34, 37-38, 41-43, 43, 16, 34, 39, 41-42, 26, 43, 43, 1, 14, 23-24, 26, 39","2":"10, 21-23, 4, 22, 28, 30, 5, 23, 24, 23, 23, 4","3":"3, 5, 8-9, 12, 16-17, 19-20, 2, 7-8, 10-11, 11, 6-7"},"q":[{"src":"brief","b":0,"text":"an amount equal to— (A) the value of nonforfeitable benefits under the plan, less (B) the value of the assets of the plan.","cite":"29 U.S.C. 1393(c)"},{"src":"brief","b":0,"text":"actuarial assumptions and methods which, in the aggregate, are reasonable (taking into account the experience of the plan and reasonable expectations) and which, in combination, offer the actuary’s best estimate of anticipated experience under the plan.","cite":"29 U.S.C. 1393(a)(1)"},{"src":"brief","b":2,"text":"actuarial assumptions and methods which, in the aggregate, are reasonable (taking into account the experience of the plan and reasonable expectations) and which, in combination, offer the actuary’s best estimate of anticipated experience under the plan.","cite":"29 U.S.C. 1393(a)(1)"},{"src":"brief","b":2,"text":"in combination, offer the actuary’s best estimate of anticipated experience under the plan.","cite":"29 U.S.C. 1393(a)(1)"},{"src":"brief","b":3,"text":"(A) the value of nonforfeitable benefits under the plan, less (B) the value of the assets of the plan.","cite":"29 U.S.C. 1393(c)"},{"src":"brief","b":3,"text":"actuary’s best estimate of anticipated experience under the plan.","cite":"29 U.S.C. 1393(a)(1)"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"assumptions and methods set forth in the [Pension Beneft Guaranty Corporation's] regulations.","cite":"29 U. S. C. § 1393(a)(2)"},{"src":"argument","who":"Mr. Barber","text":"Section 1393 explicitly governs the actuarial assumptions for withdrawal liability without saying anything about timing, whereas Section 1394 explicitly addresses retroactivity without saying anything about the assumptions."},{"src":"argument","who":"Mr. Barber","text":"So one of the upshots and one of the anomalies in Petitioners' position is that it would require the use of stale assumptions, which, as we discuss in our brief, is inconsistent with Section 1393's best estimate requirement."},{"src":"argument","who":"Mr. Barber","text":"It would affect the substantive range of permissible discount rates to use, and that would be promulgated under a different provision of Section 1393 than the one that we're dealing with here."}]},{"t":"usc","label":"29 U.S.C. § 1394","url":"https://www.law.cornell.edu/uscode/text/29/1394","subs":["(a)"],"stext":{"head":"§1394. Application of plan amendments; exception","paras":[[0,"(a) No plan rule or amendment adopted after January 31, 1981, under section 1389 or 1391(c) of this title may be applied without the employer's consent with respect to liability for a withdrawal or partial withdrawal which occurred before the date on which the rule or amendment was adopted."],[0,"(b) All plan rules and amendments authorized under this part shall operate and be applied uniformly with respect to each employer, except that special provisions may be made to take into account the creditworthiness of an employer. The plan sponsor shall give notice to all employers who have an obligation to contribute under the plan and to all employee organizations representing employees covered under the plan of any plan rules or amendments adopted pursuant to this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1394?type=usc&year=mostrecent&link-type=html"},"by":{"0":"45, 15, 30, 32","2":"8, 10, 19-21, 31, 19, 21","3":"17-19"},"q":[{"src":"brief","b":2,"text":"may be applied without the employer’s consent with respect to liability for a withdrawal or partial withdrawal which occurred before the date on which the rule or amendment was adopted.","cite":"29 U.S.C. 1394(a)"},{"src":"argument","who":"Mr. Roberts","text":"It's all about this idea that the legislative history of -- of Section 1394, which doesn't even deal with assumptions, you know, shows some general congressional interest in anti-retroactivity."},{"src":"argument","who":"Mr. Barber","text":"Section 1393 explicitly governs the actuarial assumptions for withdrawal liability without saying anything about timing, whereas Section 1394 explicitly addresses retroactivity without saying anything about the assumptions."}]},{"t":"usc","label":"29 U.S.C. § 1399","url":"https://www.law.cornell.edu/uscode/text/29/1399","subs":["(c)(1)(B)"],"by":{"0":"45"},"q":[{"src":"argument","who":"Mr. Roberts","text":"So -- so, first, under 13- -- Section 1399, the employer has to assess withdrawal liability within a practicable amount of time from the time of the withdrawal."}]},{"t":"usc","label":"29 U.S.C. § 1401","url":"https://www.law.cornell.edu/uscode/text/29/1401","subs":["(a)","(b)","(a)(3)(B)","(b)(2)"],"stext":{"head":"§1401. Resolution of disputes","paras":[[0,"(a) Arbitration proceedings; matters subject to arbitration, procedures applicable, etc."],[0,"(1) Any dispute between an employer and the plan sponsor of a multiemployer plan concerning a determination made under sections 1381 through 1399 of this title shall be resolved through arbitration. Either party may initiate the arbitration proceeding within a 60-day period after the earlier of—"],[1,"(A) the date of notification to the employer under section 1399(b)(2)(B) of this title, or"],[1,"(B) 120 days after the date of the employer's request under section 1399(b)(2)(A) of this title."],[0,"The parties may jointly initiate arbitration within the 180-day period after the date of the plan sponsor's demand under section 1399(b)(1) of this title."],[0,"(2) An arbitration proceeding under this section shall be conducted in accordance with fair and equitable procedures to be promulgated by the corporation. The plan sponsor may purchase insurance to cover potential liability of the arbitrator. If the parties have not provided for the costs of the arbitration, including arbitrator's fees, by agreement, the arbitrator shall assess such fees. The arbitrator may also award reasonable attorney's fees."],[0,"(3)(A) For purposes of any proceeding under this section, any determination made by a plan sponsor under sections 1381 through 1399 of this title and section 1405 of this title is presumed correct unless the party contesting the determination shows by a preponderance of the evidence that the determination was unreasonable or clearly erroneous."],[0,"(B) In the case of the determination of a plan's unfunded vested benefits for a plan year, the determination is presumed correct unless a party contesting the determination shows by a preponderance of evidence that—"],[1,"(i) the actuarial assumptions and methods used in the determination were, in the aggregate, unreasonable (taking into account the experience of the plan and reasonable expectations), or"],[1,"(ii) the plan's actuary made a significant error in applying the actuarial assumptions or methods."],[0,"(b) Alternative collection proceedings; civil action subsequent to arbitration award; conduct of arbitration proceedings"],[0,"(1) If no arbitration proceeding has been initiated pursuant to subsection (a), the amounts demanded by the plan sponsor under section 1399(b)(1) of this title shall be due and owing on the schedule set forth by the plan sponsor. The plan sponsor may bring an action in a State or Federal court of competent jurisdiction for collection."],[0,"(2) Upon completion of the arbitration proceedings in favor of one of the parties, any party thereto may bring an action, no later than 30 days after the issuance of an arbitrator's award, in an appropriate United States district court in accordance with section 1451 of this title to enforce, vacate, or modify the arbitrator's award."],[0,"(3) Any arbitration proceedings under this section shall, to the extent consistent with this subchapter, be conducted in the same manner, subject to the same limitations, carried out with the same powers (including subpena power), and enforced in United States courts as an arbitration proceeding carried out under title 9."],[0,"(c) Presumption respecting finding of fact by arbitrator"],[0,"In any proceeding under subsection (b), there shall be a presumption, rebuttable only by a clear preponderance of the evidence, that the findings of fact made by the arbitrator were correct."],[0,"(d) Payments by employer prior and subsequent to determination by arbitrator; adjustments; failure of employer to make payments"],[0,"Payments shall be made by an employer in accordance with the determinations made under this part until the arbitrator issues a final decision with respect to the determination submitted for arbitration, with any necessary adjustments in subsequent payments for overpayments or underpayments arising out of the decision of the arbitrator with respect to the determination. If the employer fails to make timely payment in accordance with such final decision, the employer shall be treated as being delinquent in the making of a contribution required under the plan (within the meaning of section 1145 of this title)."],[0,"(e) Procedures applicable to certain disputes"],[0,"(1) In general"],[1,"If—"],[2,"(A) a plan sponsor of a plan determines that—"],[3,"(i) a complete or partial withdrawal of an employer has occurred, or"],[3,"(ii) an employer is liable for withdrawal liability payments with respect to the complete or partial withdrawal of an employer from the plan,"],[2,"(B) such determination is based in whole or in part on a finding by the plan sponsor under section 1392(c) of this title that a principal purpose of a transaction that occurred before January 1, 1999, was to evade or avoid withdrawal liability under this subtitle, and"],[2,"(C) such transaction occurred at least 5 years before the date of the complete or partial withdrawal,"],[1,"then the special rules under paragraph (2) shall be used in applying subsections (a) and (d) of this section and section 1399(c) of this title to the employer."],[0,"(2) Special rules"],[0,"(A) Determination"],[2,"Notwithstanding subsection (a)(3)—"],[3,"(i) a determination by the plan sponsor under paragraph (1)(B) shall not be presumed to be correct, and"],[3,"(ii) the plan sponsor shall have the burden to establish, by a preponderance of the evidence, the elements of the claim under section 1392(c) of this title that a principal purpose of the transaction was to evade or avoid withdrawal liability under this subtitle."],[2,"Nothing in this subparagraph shall affect the burden of establishing any other element of a claim for withdrawal liability under this subtitle."],[0,"(B) Procedure"],[2,"Notwithstanding subsection (d) and section 1399(c) of this title, if an employer contests the plan sponsor's determination under paragraph (1) through an arbitration proceeding pursuant to subsection (a), or through a claim brought in a court of competent jurisdiction, the employer shall not be obligated to make any withdrawal liability payments until a final decision in the arbitration proceeding, or in court, upholds the plan sponsor's determination."],[0,"(f) Procedures applicable to certain disputes"],[0,"(1) In general.—If—"],[1,"(A) a plan sponsor of a plan determines that—"],[2,"(i) a complete or partial withdrawal of an employer has occurred, or"],[2,"(ii) an employer is liable for withdrawal liability payments with respect to such complete or partial withdrawal, and"],[1,"(B) such determination is based in whole or in part on a finding by the plan sponsor under section 1392(c) of this title that a principal purpose of any transaction which occurred after December 31, 1998, and at least 5 years (2 years in the case of a small employer) before the date of the complete or partial withdrawal was to evade or avoid withdrawal liability under this subtitle,"],[0,"then the person against which the withdrawal liability is assessed based solely on the application of section 1392(c) of this title may elect to use the special rule under paragraph (2) in applying subsection (d) of this section and section 1399(c) of this title to such person."],[0,"(2) Special rule.—Notwithstanding subsection (d) and section 1399(c) of this title, if an electing person contests the plan sponsor's determination with respect to withdrawal liability payments under paragraph (1) through an arbitration proceeding pursuant to subsection (a), through an action brought in a court of competent jurisdiction for review of such an arbitration decision, or as otherwise permitted by law, the electing person shall not be obligated to make the withdrawal liability payments until a final decision in the arbitration proceeding, or in court, upholds the plan sponsor's determination, but only if the electing person—"],[1,"(A) provides notice to the plan sponsor of its election to apply the special rule in this paragraph within 90 days after the plan sponsor notifies the electing person of its liability by reason of the application of section 1392(c) of this title; and"],[1,"(B) if a final decision in the arbitration proceeding, or in court, of the withdrawal liability dispute has not been rendered within 12 months from the date of such notice, the electing person provides to the plan, effective as of the first day following the 12-month period, a bond issued by a corporate surety company that is an acceptable surety for purposes of section 1112 of this title, or an amount held in escrow by a bank or similar financial institution satisfactory to the plan, in an amount equal to the sum of the withdrawal liability payments that would otherwise be due under subsection (d) and section 1399(c) of this title for the 12-month period beginning with the first anniversary of such notice. Such bond or escrow shall remain in effect until there is a final decision in the arbitration proceeding, or in court, of the withdrawal liability dispute, at which time such bond or escrow shall be paid to the plan if such final decision upholds the plan sponsor's determination."],[0,"(3) Definition of small employer.—For purposes of this subsection—"],[1,"(A) In general.—The term \"small employer\" means any employer which, for the calendar year in which the transaction referred to in paragraph (1)(B) occurred and for each of the 3 preceding years, on average—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/1401?type=usc&year=mostrecent&link-type=html"},"by":{"0":"12, 13","2":"6, 28, 30, 6"},"q":[{"src":"brief","b":2,"text":"to enforce, vacate, or modify the arbitrator’s award.","cite":"29 U.S.C. 1401(b)(2)"},{"src":"brief","b":2,"text":"the plan’s actuary made a significant error in applying the actuarial assumptions or methods.","cite":"29 U.S.C. 1401(a)(3)(B)"}]},{"t":"usc","label":"29 U.S.C. § 1405","url":"https://www.law.cornell.edu/uscode/text/29/1405","by":{"0":"45"}},{"t":"law","label":"Pub. L. No. 96-364","url":"https://www.govinfo.gov/link/statute/94/1208","by":{"0":"7, 9","2":"4"}},{"t":"law","label":"Pub. L. No. 101-239","url":"https://www.govinfo.gov/link/statute/103/2106","by":{"0":"8"}},{"t":"reg","label":"29 C.F.R. § 4065.3","url":"https://www.ecfr.gov/current/title-29/section-4065.3","subs":["(b)"],"by":{"0":"7, 33"}},{"t":"reg","label":"Methods for Computing Withdrawal Liability; Reallocation Liability Upon Mass Withdrawal; Pension Protection Act of 2006, 73 Fed. Reg. 79,628","url":"https://www.govinfo.gov/link/fr/73/79628","by":{"0":"19"}},{"t":"reg","label":"Revision of Schedule B (Actuarial Information) and Permanent Waiver of Certain Actuarial Information in the Annual Report, 44 Fed. Reg. 5440","url":"https://www.govinfo.gov/link/fr/44/5440","by":{"0":"33"}},{"t":"case","label":"Becerra v. Empire Health Found.","cite":"597 U.S. 424","y":2022,"id":"2021/20-1312","sc":1,"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"when a statute is addressed to specialists, it must be read by judges with the minds of the specialists.","cite":"597 U.S. 424, 434"},{"src":"opinion","who":"Opinion of the Court (Justice Jackson)","text":"must be read by judges with the minds of the specialists.","cite":"597 U. S. 424, 434"}]},{"t":"case","label":"BP P.L.C. v. Mayor & City Council of Balt.","cite":"141 S. Ct. 1532","y":2021,"id":"2020/19-1189","sc":1,"by":{"1":"30"}},{"t":"case","label":"Combs v. Classic Coal Corp.","cite":"1990 WL 66583","y":1990,"court":"D.D.C. Apr. 6","by":{"1":"24"}},{"t":"case","label":"FCC v. AT&T Inc.","cite":"562 U.S. 397","y":2011,"id":"2010/09-1279","sc":1,"by":{"1":"17"},"q":[{"src":"brief","b":1,"text":"[S]tatutory interpretation turns on the language itself, the specific context in which that language is used, and the broader context of the statute as a whole.","cite":"562 U.S. 397, 407"}]},{"t":"case","label":"Mertens v. Hewitt Assocs.","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"by":{"1":"30"}},{"t":"case","label":"Romag Fasteners, Inc. v. Fossil Grp., Inc.","cite":"590 U.S. 212","y":2020,"id":"2019/18-1233","sc":1,"by":{"1":"18","2":"15"},"q":[{"src":"brief","b":1,"text":"read into statutes words that aren’t there.","cite":"590 U.S. 212, 215"}]},{"t":"case","label":"Sandoz Inc. v. Amgen Inc.","cite":"582 U.S. 1","y":2017,"id":"2016/15-1039","sc":1,"by":{"1":"16, 30, 31","2":"20","3":"18"},"q":[{"src":"brief","b":1,"text":"primary guide to Congress’s preferred policy.","cite":"582 U.S. at 21"},{"src":"brief","b":1,"text":"Where . . . a statute expressly provides a remedy, courts must be especially reluctant to provide additional remedies.","cite":"582 U.S. at 16"}]},{"t":"case","label":"SAS Inst., Inc. v. Iancu","cite":"584 U.S. 357","y":2018,"id":"2017/16-969","sc":1,"by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"properly addressed to Congress, not this Court.","cite":"584 U.S. 357, 368"}]},{"t":"case","label":"Transpro, Inc. v. Leggett & Platt, Inc.","cite":"297 F. App’x 434","y":2008,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/297/434/","by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"balance sheets are routinely prepared ‘as of’ a closing date using information acquired and learned after that date.","cite":"297 F. App’x 434, 441–42"}]},{"t":"case","label":"Trs. of Loc. 138 Pension Tr. Fund v. F.W. Honerkamp Co.","cite":"692 F.3d 127","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/692/127/","by":{"1":"5"}},{"t":"case","label":"United States v. Munro-Van Helms Co.","cite":"243 F.2d 10","y":1957,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/243/10/","by":{"1":"23","2":"12"}},{"t":"case","label":"Utah Dep’t of Transp. v. Boggess-Draper Co.","cite":"467 P.3d 840","y":2020,"court":"Utah","url":"https://www.courtlistener.com/c/P.3d/467/840/","by":{"1":"26","3":"13"}},{"t":"case","label":"Cooter & Gell v. Hartmarx Corp.","cite":"496 U.S. 384","y":1990,"id":"1989/89-275","sc":1,"by":{"2":"30"}},{"t":"case","label":"E.I. DuPont de Nemours & Co. v. Davis","cite":"264 U.S. 456","y":1924,"id":"scdb/1923-110","sc":1,"by":{"2":"21"},"q":[{"src":"brief","b":2,"text":"we should naturally expect to find it in [the part of the statute] where such matters are exclusively dealt with.","cite":"264 U.S. 456, 461"}]},{"t":"case","label":"Eastman Kodak Co. v. Image Tech. Servs., Inc.","cite":"504 U.S. 451","y":1992,"id":"1991/90-1029","sc":1,"by":{"2":"32"}},{"t":"case","label":"Esteras v. United States","cite":"145 S. Ct. 2031","y":2025,"id":"2024/23-7483","sc":1,"by":{"2":"33"}},{"t":"case","label":"Gallardo v. Marstiller","cite":"596 U.S. 420","y":2022,"id":"2021/20-1263","sc":1,"by":{"2":"20","3":"18"}},{"t":"case","label":"Latimore v. Citibank Fed. Sav. Bank","cite":"151 F.3d 712","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/151/712/","by":{"2":"16"}},{"t":"case","label":"Liteky v. United States","cite":"510 U.S. 540","y":1994,"id":"1993/92-6921","sc":1,"by":{"2":"24"},"q":[{"src":"brief","b":2,"text":"cause the statute, in a significant sense, to contradict itself.","cite":"510 U.S. 540, 552"}]},{"t":"case","label":"Massaro v. Palladino","cite":"19 F.4th 197","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/19/197/","by":{"2":"5"}},{"t":"case","label":"Okerlund v. United States","cite":"365 F.3d 1044","y":2004,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/365/1044/","by":{"2":"17"}},{"t":"case","label":"Pension Benefit Guar. Corp. v. Yahn & McDonnell, Inc.","cite":"481 U.S. 735","y":1987,"id":"1986/86-231","sc":1,"by":{"2":"29"}},{"t":"case","label":"Richardson v. Perales","cite":"402 U.S. 389","y":1971,"id":"1970/108","sc":1,"by":{"2":"29"}},{"t":"case","label":"Rosner v. Metropolitan Prop. & Liab. Ins. Co.","cite":"236 F.3d 96","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/236/96/","by":{"2":"14"},"q":[{"src":"brief","b":2,"text":"‘as of ’ is not merely a synonym for ‘on,’ and use of ‘as of ’ for ‘on’ is held to be improper.","cite":"236 F.3d 96, 100"},{"src":"brief","b":2,"text":"‘justified only as a device for assigning an event to one time and the report and recognition of it to another.’","cite":"236 F.3d at 100"}]},{"t":"case","label":"Sinclair Refin. Co. v. Jenkins Petroleum Process Co.","cite":"289 U.S. 689","y":1933,"id":"scdb/1932-096","sc":1,"by":{"2":"33"},"q":[{"src":"brief","b":2,"text":"a legitimate aid to the appraisal.","cite":"289 U.S. 689, 697"}]},{"t":"case","label":"Stephens v. U.S. Airways Grp., Inc.","cite":"644 F.3d 437","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/644/437/","by":{"2":"16"}},{"t":"case","label":"Truck Ins. Exch. v. Kaiser Gypsum Co.","cite":"602 U.S. 268","y":2024,"id":"2023/22-1079","sc":1,"by":{"2":"28"},"q":[{"src":"brief","b":2,"text":"generally cannot ‘surmount the plain language of the statute.’","cite":"602 U.S. 268, 284"}]},{"t":"case","label":"United Retail & Wholesale Emps. Teamsters Union Local No. 115 Pension Plan v. Yahn & McDonnell, Inc.","cite":"787 F.2d 128","y":1986,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/787/128/","by":{"2":"29"}},{"t":"case","label":"United States v. Miller","cite":"317 U.S. 369","y":1943,"id":"scdb/1942-034","sc":1,"by":{"2":"16"},"q":[{"src":"brief","b":2,"text":"involves the use of assumptions, which make it unlikely that the appraisal will reflect true value with nicety.","cite":"317 U.S. at 374"}]},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"16"}},{"t":"usc","label":"29 U.S.C. § 1054","url":"https://www.law.cornell.edu/uscode/text/29/1054","subs":["(c)(3)"],"by":{"2":"16"}},{"t":"usc","label":"29 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/29/1301","subs":["(a)(10)"],"by":{"2":"5"}},{"t":"usc","label":"29 U.S.C. § 1382","url":"https://www.law.cornell.edu/uscode/text/29/1382","by":{"2":"5"}},{"t":"usc","label":"29 U.S.C. § 1432","url":"https://www.law.cornell.edu/uscode/text/29/1432","subs":["(c)(1)","(c)(2)"],"by":{"2":"20, 20"}},{"t":"reg","label":"87 Fed. Reg. 62,316","url":"https://www.govinfo.gov/link/fr/87/62316","by":{"2":"4, 5"}},{"t":"case","label":"Azar v. Allina Health Servs.","cite":"587 U.S. 566","y":2019,"id":"2018/17-1484","sc":1,"by":{"3":"10"},"q":[{"src":"brief","b":3,"text":"This Court does not lightly assume that Congress silently attaches different meanings to the same term in the same or related statutes.","cite":"587 U.S. 566, 574"}]},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"by":{"3":"16"},"q":[{"src":"brief","b":3,"text":"as a symmetrical and coherent regulatory scheme.","cite":"529 U.S. 120, 133"}]},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"586 U.S. 105","y":2019,"id":"2018/17-340","sc":1,"by":{"3":"23"},"q":[{"src":"brief","b":3,"text":"at the time Congress enacted the statute.","cite":"586 U.S. 105, 113"}]}]};